// J12/J15 — persisted-advice invalidation. When a safety-relevant record is
// written (injury, symptom, restriction, surgery), previously persisted
// activity advice must not survive unexamined:
//   1. open Recommendation rows are stamped staleAt/staleReason
//   2. unread activity-advice Notification rows are suppressed (deleted) —
//      they are regenerated by producers on the next cycle with fresh context
// Both are called from the activity-safety write routes AFTER the record commits.
const ACTIVITY_ADVICE_TYPES = new Set([
  'activity.suggestion', 'coach.push', 'workout.reminder', 'progress.workout_nudge',
  'plan.reminder', 'today.action', 'recovery.suggestion',
]);

async function latestSafetyEventAt(prisma, userId) {
  const [inj, sym, rst, sx] = await Promise.all([
    prisma.userInjury.aggregate({ where: { userId }, _max: { updatedAt: true } }).catch(() => null),
    prisma.userSymptomReport.aggregate({ where: { userId }, _max: { createdAt: true } }).catch(() => null),
    prisma.userActivityRestriction.aggregate({ where: { userId }, _max: { updatedAt: true } }).catch(() => null),
    prisma.userSurgery.aggregate({ where: { userId }, _max: { updatedAt: true } }).catch(() => null),
  ]);
  const ts = [inj?._max?.updatedAt, sym?._max?.createdAt, rst?._max?.updatedAt, sx?._max?.updatedAt].filter(Boolean).map(d => +new Date(d));
  return ts.length ? new Date(Math.max(...ts)) : null;
}

async function invalidateSafetyAdvice(prisma, userId, reason = 'safety_record_changed') {
  const now = new Date();
  const rec = await prisma.recommendation.updateMany({
    where: { userId, completed: false, staleAt: null },
    data: { staleAt: now, staleReason: reason },
  }).catch(() => ({ count: 0 }));
  const notif = await prisma.notification.deleteMany({
    where: { userId, read: false, type: { in: [...ACTIVITY_ADVICE_TYPES] } },
  }).catch(() => ({ count: 0 }));
  try { require('./observe').observe('safety.invalidation', { reason, count: notif.count, userId }); } catch {}
  return { recommendationsStale: rec.count, notificationsSuppressed: notif.count };
}

// J15 send-time check: before persisting an activity-advice notification, re-run
// the gate — if the verdict suppresses pushes (urgent/blocked/no candidate), do
// not create the row at all. Callers pass a body builder so suppression leaves
// no stale copy.
async function activityAdviceAllowed(prisma, userId, { gate } = {}) {
  try {
    const { safetyGate } = require('./gate');
    const g = gate || await safetyGate(prisma, userId);
    if (!g?.enabled) return { allowed: true, via: 'gate-disabled' };
    if (g.suppressActivityPushes || g.reviewRequired) { require('./observe').observe('safety.push.suppressed', { via: g.status || 'review', userId }); return { allowed: false, via: g.status || 'review' }; }
    return { allowed: g.activityPushOk !== false, via: 'gate' };
  } catch { return { allowed: false, via: 'gate-error' }; } // fail closed
}

module.exports = { ACTIVITY_ADVICE_TYPES, latestSafetyEventAt, invalidateSafetyAdvice, activityAdviceAllowed };
